### I can 100% confirm that it's only caused by loading `JPG` images from network. Other formats work fine like `PNG, WEBP, GIF`. Below is a quick example code. 

Also, my temporary solution to my project is to convert `JPG` to `WEBP`. I also use `Unsplash` and there's a `fm` query parameter which I simply change the value from `JPG` to `WEBP`. Uploaded images by the user is automatically converted from `JPG` to `WEBP`.

```
import 'package:flutter/material.dart';

// WITH ERROR
const jpgUrl = 'https://<redacted-host>/Fujjyiq.jpg';

// NO ERROR
const pngUrl = 'https://<redacted-host>/GW4HQ1r.png';
const gifUrl = 'https://<redacted-host>/xGsVWHl.gif';
const webpUrl = 'https://<redacted-host>/AAYFxi8_d.webp';

void main() {
  runApp(const MainApp());
}

class MainApp extends StatelessWidget {
  const MainApp({super.key});

  @override
  Widget build(BuildContext context) {
    return const MaterialApp(home: TestScreen());
  }
}

class TestScreen extends StatefulWidget {
  const TestScreen({super.key});

  @override
  State<TestScreen> createState() => _TestScreenState();
}

class _TestScreenState extends State<TestScreen> {
  final TextEditingController _imageUrlController = TextEditingController();
  String _imageUrl = pngUrl;

  @override
  Widget build(BuildContext context) {
    final image = Image.network(
      _imageUrl,
      width: 500,
      errorBuilder: (context, error, stackTrace) {
        return Text('Error: ${error.toString()}');
      },
    );

    final controls = Row(
      children: [
        Expanded(
          child: TextField(
            controller: _imageUrlController,
            decoration: const InputDecoration(labelText: 'Enter image URL'),
          ),
        ),
        ElevatedButton(
          onPressed: () => setState(
            () => _imageUrl = _imageUrlController.text.trim(),
          ),
          child: const Text('Update'),
        ),
      ],
    );

    return Scaffold(
      body: Padding(
        padding: const EdgeInsets.all(50),
        child: Column(
          children: [controls, const SizedBox(height: 50), image],
        ),
      ),
    );
  }
}

```

